def hydrate_time(nanoseconds, tz=None):
    # Convert nanoseconds to seconds
    seconds = nanoseconds / 1e9
    # Create a datetime object using the seconds and timezone
    from datetime import datetime, timezone
    if tz is None:
        dt = datetime.fromtimestamp(seconds)
    else:
        dt = datetime.fromtimestamp(seconds, tz=timezone(tz))

    # Create a Time object from the datetime object
    from datetime import time
    return time(dt.hour, dt.minute, dt.second, dt.microsecond * 1000)

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timedelta, timezone
    from decimal import Decimal

    if nanoseconds is None:
        return None

    nanoseconds = Decimal(nanoseconds)
    seconds = nanoseconds / Decimal(1e9)

    if tz:
        return datetime.fromtimestamp(seconds, tz=tz)
    else:
        return datetime.fromtimestamp(seconds)

