    """ Dynamically create a Point subclass.
    """

    class PointMeta(type):
        def __new__(cls, name, bases, dct):
            dct['srid'] = dct.get('srid', 'InvalidSRID')
            return super().__new__(cls, name, bases, dct)

    class Point(**fields, metaclass=PointMeta):
