def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    sentinel = object()

    class TLRUCache(Cache):
        def __init__(self, maxsize, ttl, timer, typed):
            self.cache = OrderedDict()
            self.ttl = ttl
            self.timer = timer
            self.typed = typed
            self.maxsize = maxsize if maxsize is not None else 128

        def __getitem__(self, key):
            value, expire = self.cache[key]
            if expire < self.timer():
                del self.cache[key]
                raise KeyError(key)
            return value

        def __setitem__(self, key, value):
            expire = self.timer() + self.ttl
            self.cache[key] = (value, expire)
            if len(self.cache) > self.maxsize:
                oldest = next(iter(self.cache))
                del self.cache[oldest]

        def __contains__(self, key):
            try:
                self[key]
            except KeyError:
                return False
            else:
                return True

        def __iter__(self):
            for key in self.cache:
                try:
                    self[key]
                except KeyError:
                    continue
                yield key

        def __reversed__(self):
            for key in reversed(self.cache):
                try:
                    self[key]
                except KeyError:
                    continue
                yield key

    def decorator(func):
        def wrapper(*args, **kwargs):
           cache_key = args if typed else tuple(args) + tuple(kwargs.items())
            try:
                return cache[cache_key]
            except KeyError:
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper

    cache = TLRUCache(maxsize, ttl, timer, typed)
    return decorator

