def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = lru_cache(maxsize, typed=typed)(func)
        cache.ttl = ttl
        cache.timer = timer

        @wraps(func)
        def wrapper(*args, **kwargs):
            with cache_lock:
                now = cache.timer()
                for key, (result, expires) in cache.cache.items():
                    if expires <= now:
                        del cache.cache[key]
                return cache(*args, **kwargs)

        @property
        def cache_info():
            with cache_lock:
               hits = cache.hits
                misses = cache.misses
                maxsize = cache.maxsize
                currsize = len(cache.cache)
                return hits, misses, maxsize, currsize

        wrapper.cache_info = cache_info

        return wrapper

    return decorator
