def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from collections import OrderedDict
    from operator import itemgetter

    def decorator(func):
        class Node:
            def __init__(self, key, value, freq=1):
                self.key = key
                self.value = value
                self.freq = freq

        class LFUCache:
            def __init__(self, maxsize):
                self.cache = OrderedDict()
                self.freqs = OrderedDict()
                self.maxsize = maxsize if maxsize is not None else float('inf')
                self.current_size = 0

            def _evict(self):
                if self.current_size > self.maxsize:
                    min_freq = next(iter(self.freqs.keys()))
                    key, _ = next(iter(self.freqs[min_freq].items()))
                    del self.cache[key]
                    del self.freqs[min_freq][key]
                    self.current_size -= 1

            def get(self, key):
                if key not in self.cache:
                    return None
                node = self.cache[key]
                self.frequency_incr(key, 1)
                return node.value

            def set(self, key, value):
                if key in self.cache:
                    old_node = self.cache[key]
                    self.cache.move_to_end(key)
                    self.frequency_incr(key, 1)
                    old_node.value = value
                else:
                    if self.current_size == self.maxsize:
                        self._evict()
                    node = Node(key, value)
                    self.cache[key] = node
                    if node.freq not in self.freqs:
                        self.freqs[node.freq] = OrderedDict()
                    self.freqs[node.freq][key] = node
                    self.current_size += 1

            def frequency_incr(self, key, step=1):
                node = self.cache[key]
                old_freq = node.freq
                self.freqs[old_freq].pop(key)
                node.freq += step
                if node.freq not in self.freqs:
                    self.freqs[node.freq] = OrderedDict()
                self.freqs[node.freq][key] = node
                if not self.freqs[old_freq]:
                    del self.freqs[old_freq]

        def wrapper(*args, **kwargs):
            key = (func, args, tuple(kwargs.items())) if typed else (func, args)
            if key not in lfu_cache.cache:
                lfu_cache.cache[key] = LFUCache(maxsize)
            lfu_cache_obj = lfu_cache.cache[key]
            return lfu_cache_obj.get(key)
        return wrapper
    return decorator

