def _legacy_mergeOrderings(orderings):
    merged = []
    while orderings:
        found = False
        for ordering in orderings[:]:
            if not merged or ordering[0] == merged[-1]:
                merged.extend(ordering[1:])
                orderings.remove(ordering)
                found = True
                break
            elif ordering[-1] in merged:
                pos = merged.index(ordering[-1])
                merged = merged[:pos+1] + ordering[:-1] + merged[pos+1:]
                orderings.remove(ordering)
                found = True
                break
        if not found:
            break
    return merged

