def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal_classes = []
    for cls in classes:
        for mcls in minimal_classes:
            if issubclass(cls, mcls):
                break
        else:
            minimal_classes.append(cls)
            for mcls in minimal_classes[:minimal_classes.index(cls)]:
                if cls not in mcls.__subclasses__():
                    minimal_classes.remove(mcls)
    return minimal_classes

