            context["value"]["y"] = []
        context["value"]["y"].extend(self.fields["t"])
    if "error_E_low" in self.fields:
        if "z" not in context["error"]:
            context["error"]["z"] = {"index": self.fields["error_E_low"].index(min(self.fields["error_E_low"]))}
        context["error"]["z"]["value"] = min(self.fields["error_E_low"])
