            if error_name not in context['error']:
                context['error'][error_name] = {}
            context['error'][error_name]['message'] = value
        else:
            if key not in context:
                context[key] = value
            elif isinstance(context[key], dict) and isinstance(value, dict):
                context[key].update(value)
