    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    if 'error' in self._fields:
        error_field = self._fields['error']
        if error_field in self._data:
            for i, value in enumerate(self._data[error_field]):
                if not value:
                    if 'x_low' not in context['error']:
                        context['error']['x_low'] = {'index': i}
                    else:
                        context['error']['x_low'].append(i)

    for field, data in self._data.items():
        if field not in context['value']:
            context['value'][field] = data
        else:
            context['value'][field].extend(data)

