def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self.edges is None:
        raise ValueError("Histogram edges not set")

    if isinstance(coord, (int, np.integer)):
        coord = [coord]

    if not isinstance(coord, (list, np.ndarray)):
        raise ValueError("Invalid coordinate type")

    for c in coord:
        if c < self.edges[0] or c > self.edges[-1]:
            continue

        bin_index = bisect.bisect_right(self.edges, c) - 1
        self.values[bin_index] += weight

