def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    import warnings
    from django.core.exceptions import ValidationError

    class LabelsMeta(type):
        REGEXES = {}

    class Labels(metaclass=LabelsMeta):
        pass

    warnings.filterwarnings("ignore", message="string pattern match", category=DeprecationWarning)

    def _validate_value(value, regex):
        if isinstance(value, (list, dict)):
            return all(_validate_value(v, regex) for v in value)
        else:
            return re.fullmatch(regex, value)

    def _get_error_message(key, value, regex):
        if isinstance(value, (list, dict)):
            return {value: _get_error_message(value, regex, regex)}
        else:
            return {key: f"Label {key!r} does not match the regex {regex!r}"}

    errors = []
    for key, value in labels.items():
        if not isinstance(key, str):
            key = str(key)
        if isinstance(value, list):
            value = [str(v) for v in value]
        elif isinstance(value, dict):
            value = {k: str(v) for k, v in value.items()}
        regex = getattr(Labels, LabelsMeta.REGEXES.get(key, 'default_regex'), '[0-9]+')
        if not _validate_value(value, regex):
            errors.append(_get_error_message(key, value, regex))

    if errors:
        raise ValidationError({'labels': errors})

