    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple):
            if expr[0] == 'and':
                if expr[1][0] == 'or' and expr[1][0][1][0] == expr[0][1]:
                    result.append(expr[0][1])
            elif expr[0] == 'or':
                if expr[1][0] == 'and' and expr[1][0][1][0] == expr[0][1]:
                    result.append(expr[0][1])
        else:
            result.append(expr)
    return result

