def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 2:
            op, subexpr = expr
            if op in ('&', '|'):
                if isinstance(subexpr, tuple) and len(subexpr) == 2:
                    subop, subsubexpr = subexpr
                    if subop == op:
                        new_expr = (op, subexpr[1])
                        result.append(new_expr)
                    elif subop == ('~', op):
                        new_expr = op, (op, subsubexpr[1])
                        result.append(new_expr)
                else:
                    result.append(expr)
            else:
                result.append(expr)
        else:
            result.append(expr)
    return result

