def deep_merge_nodes(nodes):
    result = {}
    for key_node, value_node in nodes:
        if key_node.value not in result:
            result[key_node.value] = value_node
        else:
            if isinstance(result[key_node.value], ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                value_node.value = _merge_mappings(result[key_node.value].value, value_node.value)
            else:
                result[key_node.value] = value_node
    return [(key_node, result[key_node]) for key_node in result]

def _merge_mappings(lhs, rhs):
    combined_dict = itertools.chain(lhs, rhs)
    merged_dict = {}
    for key, value in combined_dict:
        if key in merged_dict:
            if isinstance(merged_dict[key], dict) and isinstance(value, dict):
                merged_dict[key] = _merge_mappings(merged_dict[key], value)
            else:
                merged_dict[key] = value
        else:
            merged_dict[key] = value
    return [(key, value) for key, value in merged_dict.items()]

