def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    size_info = size.strip().upper().replace(' ', '')
    size_value = int(float(size_info[:-1]))
    size_unit = size_info[-1]

    if size_unit == 'B':
        return size_value
    elif size_unit == 'K':
        return size_value * 1024
    elif size_unit == 'M':
        return size_value * 1024 * 1024
    elif size_unit == 'G':
        return size_value * 1024 * 1024 * 1024
    elif size_unit == 'T':
        return size_value * 1024 * 1024 * 1024 * 1024
    elif size_unit == 'P':
        return size_value * 1024 * 1024 * 1024 * 1024 * 1024
    elif size_unit == 'E':
        return size_value * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    elif size_unit == 'Z':
        return size_value * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    elif size_unit == 'Y':
        return size_value * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    else:
        raise ValueError(f"Invalid size unit: {size_unit}")
