def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    base = len(alphabet)
    inverse_alphabet = dict(zip(alphabet, range(0, base)))
    result = ""

    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    if padding:
        result = result.zfill(padding)

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    if number == 0:
        return alphabet[0] * (padding or 1)

    digits = []
    base = len(alphabet)
    while number:
        digits.append(alphabet[number % base])
        number //= base

    if padding is not None and len(digits) < padding:
        digits += [alphabet[0]] * (padding - len(digits))

    return ''.join(reversed(digits))

