def subclasses(cls):
    """Return all subclasses of a class, recursively"""

    seen = set()
    queue = set([cls])

    while queue:
        current = queue.pop()
        seen.add(current)

        sc = current.__subclasses__()
        for subclass in sc:
            if subclass not in seen:
                queue.add(subclass)

    return seen - {cls}

def subclasses(cls):
    """Return all subclasses of a class, recursively"""

    seen = set()
    queue = [cls]

    while queue:
        current_class = queue.pop()
        seen.add(current_class)

        for subclass in current_class.__subclasses__():
            if subclass not in seen:
                queue.append(subclass)

    return list(seen)

