    if platform:
        # POSIX-like platform
        return re.findall(r'(?:(?<=\\)\s|(?<![\\])\s)', s)
    else:
        # Windows/CMD platform
        return re.findall(r'(?:(?<=\\)\s|(?<![\\])\s)', s)
