def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if filename is None:
        filename = os.path.basename(archive_path)

    temp_dir = PosixPath(tmp_path) / filename
    temp_dir.mkdir(exist_ok=True)

    try:
        if archive_path.endswith('.tar.gz'):
            subprocess.check_call(['tar', '-xzf', archive_path, '--directory', temp_dir])
        elif archive_path.endswith('.tar.bz2'):
            subprocess.check_call(['tar', '-xjf', archive_path, '--directory', temp_dir])
        else:
            raise ValueError('Unsupported archive type')

        return str(temp_dir)
    except CalledProcessError as e:
        raise RuntimeError(f'Error extracting archive: {e}')
    except Exception as e:
        raise RuntimeError(f'Error preparing repository: {e}')
