    import subprocess
    import os

    # Combine the original args with any extra_env variables
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)

    # Prepare the command to run
    command = [func.__module__, func.__name__, *args]

    try:
        result = subprocess.run(command, env=env, timeout=timeout, check=True, capture_output=True, text=True)
        return result.stdout.strip()
    except subprocess.TimeoutExpired as e:
        raise TimeoutError(f"Process timed out after {timeout} seconds") from e
