def _apply_overrides(config, overrides):
    '''Applies overrides to the configuration dictionary.'''
    for key, value in overrides.items():
        if isinstance(value, dict):
            config[key] = _apply_overrides(config.get(key, {}), value)
        else:
            config[key] = value
    return config

def _resolve_env_vars(config):
    '''Resolves environment variables in the configuration dictionary.'''
    for key, value in config.items():
        if isinstance(value, str) and value.startswith('${'):
            env_var = value[2:-1]
            config[key] = os.getenv(env_var, value)
        elif isinstance(value, dict):
            config[key] = _resolve_env_vars(value)
    return config

