def scale(self, other=None, recompute=False):
    if other is None:
        if not recompute and hasattr(self, '_scale'):
            return self._scale
        else:
            self._scale = np.sum(self.histogram)
            return self._scale
    else:
        if self._scale == 0:
            raise LenaValueError("Histogram scale is zero, can't be rescaled.")
        rescale_factor = other / self._scale
        self.histogram *= rescale_factor
        self._scale = other
        return self._scale

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_content: bin_content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) != 2:
        raise ValueError("field_names must contain exactly two field names")

    points = []
    for bin_left, bin_right, bin_content, bin_error in zip(hist.bin_left, hist.bin_right, hist.bin_content, hist.bin_error):
        if get_coordinate == "left":
            x = bin_left
        elif get_coordinate == "right":
            x = bin_right
        elif get_coordinate == "middle":
            x = (bin_left + bin_right) / 2

        value = make_value(bin_content)
        points.append([x, value])

    if scale is True:
        scale = hist.scale

    graph = Graph(field_names, scale=scale)
    graph.add_points(points)
    return graph

