def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate directly implements the interface
    if iface in candidate.implements():
        return True

    # Check if the candidate inherits from a class that implements the interface
    if tentative:
        ancestor = candidate
        while ancestor is not None:
            if iface in ancestor.implements():
                return True
            ancestor = ancestor.getSuperclass()

    return False

def verifyClass(iface, candidate, tentative=False):
