    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)

        required_fields = {
            "field1": str,
            "field2": int,
            "field3": list
        }

        for field, field_type in required_fields.items():
            if field not in data:
                raise IRValidatorException(f"Missing required field '{field}' in YAML file")
            if not isinstance(data[field], field_type):
                raise IRValidatorException(f"Field '{field}' must be of type {field_type.__name__}")

        return data

    except FileNotFoundError:
        raise IRValidatorException(f"YAML file not found at {yaml_file}")
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {e}")
