    """Resolves the include dict directive in the spec files. """
    include_dict = parser_dict.get('include', {})
    for key, value in include_dict.items():
        if key == 'groups':
            for group_name, group_info in value.items():
                parser_dict['groups'][group_name] = group_info
        elif key == 'options':
            for option_name, option_info in value.items():
