def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_args_mapping = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2',
        # Add more deprecated args mapping as needed
    }

    def warn_deprecated_arg(deprecated_arg, new_arg):
        warnings.warn(
            f"Argument '{deprecated_arg}' has been deprecated in favor of '{new_arg}'. '{deprecated_arg}' will be removed in a future version.",
            category=DeprecationWarning,
            stacklevel=2,
        )

    for deprecated_arg, new_arg in deprecated_args_mapping.items():
        if deprecated_arg in cli_args:
            warn_deprecated_arg(deprecated_arg, new_arg)
            answer_file_args[new_arg] = cli_args.pop(deprecated_arg)
        elif deprecated_arg in answer_file_args:
            warn_deprecated_arg(deprecated_arg, new_arg)

    return answer_file_args
