def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_args = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2'
    }

    for arg, value in cli_args.items():
        if arg in deprecated_args:
            warnings.warn(
                "Argument '{}' has been deprecated in favour of '{}'.".format(
                    arg, deprecated_args[arg]
                ),
                category=UserWarning,
                stacklevel=2
            )
            cli_args[deprecated_args[arg]] = value
            del cli_args[arg]

    for arg, value in answer_file_args.items():
        if arg in deprecated_args:
            warnings.warn(
                "Argument '{}' has been deprecated in favour of '{}'.".format(
                    arg, deprecated_args[arg]
                ),
                category=UserWarning,
                stacklevel=2
            )
            answer_file_args[deprecated_args[arg]] = value
            del answer_file_args[arg]

    return cli_args, answer_file_args
