            if not min_value <= arg <= max_value:
                raise ValueError(
                    f"Argument {arg} is out of the allowed range [{min_value}, {max_value}]"
                )
    elif min_value is not None and max_value is None:
        for arg in args:
            if arg < min_value:
                raise ValueError(
                    f"Argument {arg} is less than the minimum allowed value {min_value}"
                )
    elif min_value is None and max_value is not None:
        for arg in args:
            if arg > max_value:
                raise ValueError(
                    f"Argument {arg} is greater than the maximum allowed value {max_value}"
                )
    else:
        raise ValueError(
            "Either min_value and max_value must be provided together or one of them"
        )

