def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = getattr(self, f'_{parser_name}_parser')

    for action in parser._actions:
        if action.dest in values_dict:
            if action.nargs == argparse.OPTIONAL:
                values_dict[action.dest] = action.type(values_dict[action.dest]) if values_dict[action.dest] is not None else action.default
            else:
                values_dict[action.dest] = [action.type(value) for value in values_dict[action.dest]]

    return values_dict

