def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    from os.path import join, isfile
    from os import listdir

    flatten_dict = {}

    def _flatten_dict(d, parent_key='', sep='_'):
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten_dict(v, new_key, sep)
            else:
                flatten_dict[new_key] = v

    for file_name in listdir(plugin_dir):
        file_path = join(plugin_dir, file_name)
        if isfile(file_path):
            with open(file_path, 'r') as file:
                file_data = file.read()
                _flatten_dict(eval(file_data))

    return flatten_dict
